// GOOD: only allow http(s) URLs in href/src
function safeHref(input) {
  try {
    const url = new URL(input, location.origin);
    return url.protocol === 'https:' || url.protocol === 'http:' ? url.href : '#';
  } catch {
    return '#';
  }
}
